control 'CKV_AWS_230' do
  title 'Ensure no NACL allow ingress from 0.0.0.0:0 to port 20'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_network_acl resources that actually exist, enumerated through
